css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; position: relative; background: conic-gradient(from 0deg, transparent, var(--accent) 42%, var(--accent-2) 72%, transparent); -webkit-mask: radial-gradient(circle, #000 18%, #000 62%, transparent 74%); mask: radial-gradient(circle, #000 18%, #000 62%, transparent 74%); animation: swirl calc(var(--loader-speed) * 1.5) linear infinite; }
.loader::before { content: ''; position: absolute; inset: 24%; border-radius: 50%; background: conic-gradient(from 180deg, transparent, var(--accent-2) 50%, transparent); -webkit-mask: radial-gradient(circle, transparent 22%, #000 62%, transparent); mask: radial-gradient(circle, transparent 22%, #000 62%, transparent); animation: swirl calc(var(--loader-speed) * 1) linear infinite reverse; }
@keyframes swirl { to { transform: rotate(360deg); } }
